// Single source of truth for this automation. Nothing else needs editing to retune it.
const TIMEZONE = 'Australia/Brisbane';      // 'today' and the duplicate window are read in this zone
const GUARD_LOOKBACK_DAYS = 0;              // 0 = window starts at the start of the trigger day. Set to 1 for ONE recovery run the day after a failed run, then set back to 0.

// Duplicate-check window, taken from the Schedule Trigger (not from "now"):
// from the start of the day the schedule fired, to one minute before the next weekly execution.
const runAt = DateTime.fromISO($('Schedule Trigger').first().json.timestamp, { zone: TIMEZONE });
if (!runAt.isValid) throw new Error('Schedule Trigger did not return a valid timestamp - cannot work out the duplicate-check window.');
const windowStartMs = runAt.startOf('day').minus({ days: GUARD_LOOKBACK_DAYS }).toMillis();
const windowEndMs = runAt.plus({ days: 7 }).minus({ minutes: 1 }).toMillis();

return [{
  json: {
    // ---- Xero (values carried over from the original sync workflow) ----
    xeroBatchSize: 50,          // invoices per Xero request. Xero's guidance is "up to 50"; was 100. HubSpot batch calls cap at 100.
    batchWaitSeconds: 10,       // pause between Xero batches (seconds). Keep under 65 so the execution is not offloaded to the database.
    xeroTenantId: '1e9660fb-45a7-4a9b-9158-cc54c9e78f34',   // Xero organisation (tenant) - Anicca RIT
    brandingThemeId: '294af06f-b8a6-4049-8420-763713693f3a',
    currency: 'AUD',
    invoiceStatus: 'DRAFT',     // status the invoice is created with in Xero
    // Xero rental income account by company state. Anything else (or blank) falls back to defaultAccountId.
    stateAccounts: { WA: 'WA5000', VIC: 'VIC5000', NSW: 'NSW5000' },
    defaultAccountId: 'WA5000',

    // ---- HubSpot (portal 443317712) ----
    apiBase: 'https://api.hubapi.com',
    apiVersion: '2026-09',                     // date-based HubSpot API version, read by every HubSpot request URL
    batchSize: 50,                             // ids per HubSpot batch call (HubSpot allows 100)
    openBatchSize: 10,                         // invoices per draft -> open call. Smaller than batchSize on purpose: opening is the heavy HubSpot step (a 50-invoice call returned 500 INTERNAL_ERROR on 8 Nov 2026).
    guardLookbackDays: GUARD_LOOKBACK_DAYS,    // see top of node
    windowStartMs,                             // duplicate window start (ms): start of the trigger day, minus guardLookbackDays
    windowEndMs,                               // duplicate window end (ms): trigger time + 7 days - 1 minute (one minute before the next weekly run)
    companyFlagProperty: 'asset_delivered',    // company number property: invoiced when > 0
    assetObjectType: '2-217972099',            // custom Assets object (p443317712_assets)
    billableStatuses: ['active', 'to be returned'],   // asset status, compared lower-case
    invoiceType: 'Weekly',
    invoiceCurrency: 'AUD',
    // The duplicate check looks at Weekly invoices created inside the window above (trigger day -> one minute before the next run) that have a company.
    timezone: TIMEZONE,                        // the window and the invoice dates are read in this zone
    issueWeekday: 1,                           // invoice date = the FOLLOWING Monday (1 = Monday). Run on a Monday -> next week's Monday.
    // Due date = the first such weekday on/after the invoice date, from the company's weekly_invoice_expiry_date (Tue-Fri today)
    expiryWeekdays: { Monday: 1, Tuesday: 2, Wednesday: 3, Thursday: 4, Friday: 5 },
    billingContactTypeIds: [930, 931],         // Billing Contact association types (matched with the label below)
    billingContactLabel: 'billing contact',
    assocTypeIds: { invoiceToCompany: 179, invoiceToContact: 177, lineItemToInvoice: 410 },
    companyProps: ['name', 'asset_delivered', 'state', 'xero_customer_id', 'hubspot_owner_id', 'weekly_invoice_expiry_date'],
    assetProps: ['name', 'status', 'serial_number', 'contract_number', 'asset_number', 'xero_asset_id', 'xero_item_id'],
    sourceLineItemProps: ['name', 'price', 'quantity', 'hs_product_id', 'hs_sku', 'description'],
    invoiceDetailProps: ['hs_number', 'hs_purchase_order_number', 'hubspot_owner_id', 'hs_invoice_date', 'hs_due_date', 'hs_createdate', 'hs_invoice_status', 'xero_invoice_id'],
    xeroLineItemProps: ['amount', 'price', 'quantity', 'name', 'asset_number', 'xero_asset_id', 'xero_item_id', 'description', 'serial_number']
  }
}];

const found = new Map();
let total = 0;
for (const item of $input.all()) {
  const page = item.json;
  if (typeof page.total === 'number') total = page.total;
  for (const c of page.results || []) found.set(String(c.id), c);
}
if (found.size !== total) {
  throw new Error(`Company search returned ${found.size} of ${total} companies - paging was incomplete. Aborting before anything is created.`);
}
if (!found.size) return [];      // nothing to invoice: the run ends cleanly here
const companies = {};
for (const [id, c] of found) {
  const p = c.properties || {};
  companies[id] = { name: p.name || '', state: String(p.state || '').trim(), xeroContactId: String(p.xero_customer_id || '').trim(), ownerId: p.hubspot_owner_id || '', expiryDay: String(p.weekly_invoice_expiry_date || '').trim() };
}
return [{ json: { companies, companyIds: Object.keys(companies), outcomes: {}, issues: [], pendingXero: [] } }];

const ctx = $('Collect Companies').first().json;
const found = new Map();
let total = 0;
for (const item of $input.all()) {
  const page = item.json;
  if (typeof page.total === 'number') total = page.total;
  for (const inv of page.results || []) found.set(String(inv.id), inv);
}
if (found.size !== total) {
  throw new Error(`Invoice guard search returned ${found.size} of ${total} invoices - paging was incomplete. Aborting before anything is created.`);
}
const guardInvoices = [...found.values()].map(inv => {
  const p = inv.properties || {};
  return { id: String(inv.id), status: String(p.hs_invoice_status || '').toLowerCase(), createdMs: new Date(p.hs_createdate).getTime(), xeroId: String(p.xero_invoice_id || '').trim() };
});
return [{ json: { ...ctx, guardInvoices } }];

const ctx = $input.first().json;
const size = $('Workflow Config').first().json.batchSize;
const list = ctx.guardInvoices.map(i => i.id);
const chunks = [];
for (let i = 0; i < list.length; i += size) chunks.push(list.slice(i, i + size));
// FAN-OUT: one item per batch of up to batchSize ids. The HTTP node below runs once per batch.
return chunks.map(ids => ({ json: { ids } }));

const ctx = $('Index Guard Invoices').first().json;
const cfg = $('Workflow Config').first().json;
const windowStart = cfg.windowStartMs;      // start of the trigger day (minus guardLookbackDays for a recovery run)
const windowEnd = cfg.windowEndMs;          // one minute before the next weekly execution
const selected = new Set(ctx.companyIds);
const invoiceCompany = {};
for (const item of $input.all()) {
  const r = item.json;
  if (!Array.isArray(r.results)) continue;          // the no-guard-invoices path passes the context item straight through
  // An invoice with no company comes back as a NO_ASSOCIATIONS_FOUND error entry: it is simply ignored below.
  const real = (r.errors || []).filter(e => e.subCategory !== 'crm.associations.NO_ASSOCIATIONS_FOUND');
  if (real.length || (r.numErrors > 0 && !r.errors)) {
    throw new Error(`Invoice to company read returned errors: ${JSON.stringify(real.length ? real : r.errors)}`);
  }
  for (const row of r.results) {
    const ids = (row.to || []).map(t => String(t.toObjectId)).filter(id => selected.has(id));
    if (ids.length) invoiceCompany[String(row.from.id)] = ids[0];
  }
}
const alreadyInvoiced = new Set();
const pendingXero = [];
const draftInvoiceIds = [];
for (const inv of ctx.guardInvoices) {
  const companyId = invoiceCompany[inv.id];
  if (!companyId) continue;
  if (inv.status === 'draft') { draftInvoiceIds.push(inv.id); continue; }
  if ((inv.status === 'open' || inv.status === 'paid') && inv.createdMs >= windowStart && inv.createdMs <= windowEnd) {
    alreadyInvoiced.add(companyId);
    if (inv.status === 'open' && !inv.xeroId) pendingXero.push({ invoiceId: inv.id, companyId });
  }
}
const outcomes = { ...ctx.outcomes };
for (const id of alreadyInvoiced) outcomes[id] = { status: 'already_invoiced', message: 'A Weekly invoice already exists inside the duplicate window' };
const { guardInvoices, ...rest } = ctx;
return [{ json: { ...rest, outcomes, pendingXero, draftInvoiceIds, eligibleIds: ctx.companyIds.filter(id => !alreadyInvoiced.has(id)) } }];

const ctx = $input.first().json;
const size = $('Workflow Config').first().json.batchSize;
const list = ctx.draftInvoiceIds;
const chunks = [];
for (let i = 0; i < list.length; i += size) chunks.push(list.slice(i, i + size));
// FAN-OUT: one item per batch of up to batchSize ids. The HTTP node below runs once per batch.
return chunks.map(ids => ({ json: { ids } }));

const ctx = $('Apply Guard').first().json;
const size = $('Workflow Config').first().json.batchSize;
const lineItemIds = new Set();
for (const item of $input.all()) {
  const r = item.json;
  // HubSpot reports a record with NO associations as an error entry rather than leaving it out. That is normal, not a failure.
  const real = (r.errors || []).filter(e => e.subCategory !== 'crm.associations.NO_ASSOCIATIONS_FOUND');
  if (real.length || (r.numErrors > 0 && !r.errors)) {
    throw new Error(`Draft invoice line item read returned errors: ${JSON.stringify(real.length ? real : r.errors)}`);
  }
  for (const row of r.results || []) {
    if (row.paging && row.paging.next) {
      throw new Error(`Leftover draft invoice ${row.from.id} has more line items than one read returns. Delete the draft manually in HubSpot, then re-run.`);
    }
    for (const t of row.to || []) lineItemIds.add(String(t.toObjectId));
  }
}
const chunk = (list) => {
  const out = [];
  for (let i = 0; i < list.length; i += size) out.push(list.slice(i, i + size));
  return out;
};
// FAN-OUT: line item batches first, then draft invoice batches, so a failure part-way leaves a draft that is found and cleaned again next run.
return [
  ...chunk([...lineItemIds]).map(ids => ({ json: { objectType: 'line_items', ids } })),
  ...chunk(ctx.draftInvoiceIds).map(ids => ({ json: { objectType: 'invoices', ids } }))
];

const ctx = $input.first().json;
const size = $('Workflow Config').first().json.batchSize;
const list = ctx.eligibleIds;
const chunks = [];
for (let i = 0; i < list.length; i += size) chunks.push(list.slice(i, i + size));
// FAN-OUT: one item per batch of up to batchSize ids. The HTTP node below runs once per batch.
return chunks.map(ids => ({ json: { ids } }));

const ctx = $('Guard Cleared').first().json;
const outcomes = { ...ctx.outcomes };
const issues = [...ctx.issues];
const label = (id) => `${(ctx.companies[id] || {}).name || 'Company'} (${id})`;
const assetIdsByCompany = {};
for (const item of $input.all()) {
  const r = item.json;
  // HubSpot reports a record with NO associations as an error entry rather than leaving it out. That is normal, not a failure.
  const real = (r.errors || []).filter(e => e.subCategory !== 'crm.associations.NO_ASSOCIATIONS_FOUND');
  if (real.length || (r.numErrors > 0 && !r.errors)) {
    throw new Error(`Company to asset read returned errors: ${JSON.stringify(real.length ? real : r.errors)}`);
  }
  for (const row of r.results || []) {
    const cid = String(row.from.id);
    if (row.paging && row.paging.next) {
      issues.push(`${label(cid)}: asset list is longer than one HubSpot read returns - company skipped this week`);
      outcomes[cid] = { status: 'issue', message: 'asset list longer than one read' };
      continue;
    }
    assetIdsByCompany[cid] = (row.to || []).map(t => String(t.toObjectId));
  }
}
const assetIds = new Set();
for (const cid of ctx.eligibleIds) {
  if (outcomes[cid]) continue;
  const ids = assetIdsByCompany[cid] || [];
  if (!ids.length) { outcomes[cid] = { status: 'no_assets', message: 'Company has no associated assets' }; continue; }
  ids.forEach(id => assetIds.add(id));
}
return [{ json: { ...ctx, outcomes, issues, assetIdsByCompany, assetIds: [...assetIds] } }];

const ctx = $input.first().json;
const size = $('Workflow Config').first().json.batchSize;
const list = ctx.assetIds;
const chunks = [];
for (let i = 0; i < list.length; i += size) chunks.push(list.slice(i, i + size));
// FAN-OUT: one item per batch of up to batchSize ids. The HTTP node below runs once per batch.
return chunks.map(ids => ({ json: { ids } }));

const ctx = $('Collect Asset Links').first().json;
const cfg = $('Workflow Config').first().json;
const assetById = {};
for (const item of $input.all()) {
  const r = item.json;
  if (r.numErrors > 0 || (r.errors && r.errors.length)) {
    throw new Error(`Asset read returned errors: ${JSON.stringify(r.errors)}`);
  }
  for (const a of r.results || []) assetById[String(a.id)] = a;
}
const outcomes = { ...ctx.outcomes };
const billableByCompany = {};
const billableAssetIds = [];
for (const cid of ctx.eligibleIds) {
  if (outcomes[cid]) continue;
  const billable = (ctx.assetIdsByCompany[cid] || [])
    .map(id => assetById[id])
    .filter(a => a && cfg.billableStatuses.includes(String((a.properties || {}).status || '').toLowerCase()))
    .map(a => ({
      id: String(a.id),
      serialNumber: a.properties.serial_number || '',
      contractNumber: a.properties.contract_number || '',
      assetNumber: a.properties.asset_number || '',
      xeroAssetId: a.properties.xero_asset_id || '',
      xeroItemId: a.properties.xero_item_id || ''
    }));
  if (!billable.length) { outcomes[cid] = { status: 'no_active_assets', message: 'No asset is Active or To be Returned' }; continue; }
  billableByCompany[cid] = billable;
  billable.forEach(a => billableAssetIds.push(a.id));
}
const { assetIds, assetIdsByCompany, ...rest } = ctx;
return [{ json: { ...rest, outcomes, billableByCompany, billableAssetIds } }];

const ctx = $input.first().json;
const size = $('Workflow Config').first().json.batchSize;
const list = ctx.billableAssetIds;
const chunks = [];
for (let i = 0; i < list.length; i += size) chunks.push(list.slice(i, i + size));
// FAN-OUT: one item per batch of up to batchSize ids. The HTTP node below runs once per batch.
return chunks.map(ids => ({ json: { ids } }));

const ctx = $('Collect Billable Assets').first().json;
const outcomes = { ...ctx.outcomes };
const issues = [...ctx.issues];
const label = (id) => `${(ctx.companies[id] || {}).name || 'Company'} (${id})`;
const lineItemsByAsset = {};
const pagedAssets = new Set();
for (const item of $input.all()) {
  const r = item.json;
  // HubSpot reports a record with NO associations as an error entry rather than leaving it out. That is normal, not a failure.
  const real = (r.errors || []).filter(e => e.subCategory !== 'crm.associations.NO_ASSOCIATIONS_FOUND');
  if (real.length || (r.numErrors > 0 && !r.errors)) {
    throw new Error(`Asset to line item read returned errors: ${JSON.stringify(real.length ? real : r.errors)}`);
  }
  for (const row of r.results || []) {
    if (row.paging && row.paging.next) pagedAssets.add(String(row.from.id));
    lineItemsByAsset[String(row.from.id)] = (row.to || []).map(t => String(t.toObjectId));
  }
}
const billableByCompany = {};
const lineItemIds = new Set();
for (const [cid, assets] of Object.entries(ctx.billableByCompany)) {
  if (assets.some(a => pagedAssets.has(a.id))) {
    issues.push(`${label(cid)}: an asset has more line items than one HubSpot read returns - company skipped this week`);
    outcomes[cid] = { status: 'issue', message: 'asset line item list longer than one read' };
    continue;
  }
  const ids = assets.flatMap(a => lineItemsByAsset[a.id] || []);
  if (!ids.length) { outcomes[cid] = { status: 'no_line_items', message: 'No billable asset has a line item' }; continue; }
  billableByCompany[cid] = assets;
  ids.forEach(id => lineItemIds.add(id));
}
const { billableAssetIds, ...rest } = ctx;
return [{ json: { ...rest, outcomes, issues, billableByCompany, lineItemsByAsset, lineItemIds: [...lineItemIds] } }];

const ctx = $input.first().json;
const size = $('Workflow Config').first().json.batchSize;
const list = ctx.lineItemIds;
const chunks = [];
for (let i = 0; i < list.length; i += size) chunks.push(list.slice(i, i + size));
// FAN-OUT: one item per batch of up to batchSize ids. The HTTP node below runs once per batch.
return chunks.map(ids => ({ json: { ids } }));

const ctx = $('Collect Line Item Links').first().json;
const lineItemById = {};
for (const item of $input.all()) {
  const r = item.json;
  if (r.numErrors > 0 || (r.errors && r.errors.length)) {
    throw new Error(`Line item read returned errors: ${JSON.stringify(r.errors)}`);
  }
  for (const li of r.results || []) lineItemById[String(li.id)] = li;
}
const outcomes = { ...ctx.outcomes };
const issues = [...ctx.issues];
const label = (id) => `${(ctx.companies[id] || {}).name || 'Company'} (${id})`;
const plans = {};
for (const [cid, assets] of Object.entries(ctx.billableByCompany)) {
  let fallbackSequence = 1;          // advances only when an asset has no asset_number but has a contract_number
  const lines = [];
  try {
    for (const asset of assets) {
      const ids = ctx.lineItemsByAsset[asset.id] || [];
      let assetNumber = asset.assetNumber;
      if (ids.length && !assetNumber && asset.contractNumber) assetNumber = `${asset.contractNumber}-${fallbackSequence++}`;
      for (const id of ids) {
        const li = lineItemById[String(id)];
        if (!li) throw new Error(`line item ${id} could not be read`);
        const lp = li.properties || {};
        const price = parseFloat(lp.price == null ? 0 : lp.price);
        const quantity = parseFloat(lp.quantity == null ? 1 : lp.quantity);
        if (!Number.isFinite(price) || !Number.isFinite(quantity)) throw new Error(`line item ${id} has a non-numeric price or quantity`);
        const parts = [];
        if (lp.description) parts.push(lp.description);
        if (asset.contractNumber) parts.push(`Contract: ${asset.contractNumber}`);
        if (asset.serialNumber) parts.push(`S/N: ${asset.serialNumber}`);
        const props = { name: lp.name, quantity: '1', price: (price * quantity).toFixed(2), description: parts.join(' | ') };
        if (lp.hs_product_id) props.hs_product_id = lp.hs_product_id;
        if (lp.hs_sku) props.hs_sku = lp.hs_sku;
        if (assetNumber) props.asset_number = assetNumber;
        if (asset.serialNumber) props.serial_number = asset.serialNumber;
        if (asset.xeroAssetId) props.xero_asset_id = asset.xeroAssetId;
        if (asset.xeroItemId) props.xero_item_id = asset.xeroItemId;
        lines.push(props);
      }
    }
  } catch (e) {
    issues.push(`${label(cid)}: ${e.message} - company skipped this week`);
    outcomes[cid] = { status: 'issue', message: e.message };
    continue;
  }
  if (!lines.length) { outcomes[cid] = { status: 'no_line_items', message: 'No billable asset has a line item' }; continue; }
  plans[cid] = lines;
}
const { billableByCompany, lineItemsByAsset, lineItemIds, ...rest } = ctx;
return [{ json: { ...rest, outcomes, issues, plans, planIds: Object.keys(plans) } }];

const ctx = $input.first().json;
const size = $('Workflow Config').first().json.batchSize;
const list = ctx.planIds;
const chunks = [];
for (let i = 0; i < list.length; i += size) chunks.push(list.slice(i, i + size));
// FAN-OUT: one item per batch of up to batchSize ids. The HTTP node below runs once per batch.
return chunks.map(ids => ({ json: { ids } }));

const ctx = $('Build Invoice Plan').first().json;
const cfg = $('Workflow Config').first().json;
const issues = [...ctx.issues];
const billingByCompany = {};
for (const item of $input.all()) {
  const r = item.json;
  // HubSpot reports a record with NO associations as an error entry rather than leaving it out. That is normal, not a failure.
  const real = (r.errors || []).filter(e => e.subCategory !== 'crm.associations.NO_ASSOCIATIONS_FOUND');
  if (real.length || (r.numErrors > 0 && !r.errors)) {
    throw new Error(`Company to contact read returned errors: ${JSON.stringify(real.length ? real : r.errors)}`);
  }
  for (const row of r.results || []) {
    const cid = String(row.from.id);
    const hit = (row.to || []).find(t => (t.associationTypes || []).some(a =>
      cfg.billingContactTypeIds.includes(a.typeId) || String(a.label || '').toLowerCase() === cfg.billingContactLabel));
    if (hit) billingByCompany[cid] = String(hit.toObjectId);
    else if (row.paging && row.paging.next) {
      issues.push(`${(ctx.companies[cid] || {}).name || 'Company'} (${cid}): contact list is longer than one HubSpot read returns - invoice created WITHOUT a billing contact`);
    }
  }
}
const start = DateTime.now().setZone(cfg.timezone).startOf('day');
const daysAhead = ((cfg.issueWeekday - start.weekday + 7) % 7) || 7;      // always the FOLLOWING Monday, never today
const issue = start.plus({ days: daysAhead });
const issueDate = issue.toFormat('yyyy-MM-dd');
const cat = 'HUBSPOT_DEFINED';
// Associations are set at creation so a half-built draft can always be found from its company.
const invoiceInputs = ctx.planIds.map(cid => {
  const company = ctx.companies[cid] || {};
  const weekday = cfg.expiryWeekdays[company.expiryDay];
  let dueDate = issueDate;
  if (weekday) {
    dueDate = issue.plus({ days: (weekday - issue.weekday + 7) % 7 }).toFormat('yyyy-MM-dd');
  } else {
    issues.push(`${company.name || 'Company'} (${cid}): Weekly Invoice Expiry Date is ${company.expiryDay ? '"' + company.expiryDay + '"' : 'blank'} - due date set to the invoice date`);
  }
  const associations = [{ to: { id: cid }, types: [{ associationCategory: cat, associationTypeId: cfg.assocTypeIds.invoiceToCompany }] }];
  if (billingByCompany[cid]) {
    associations.push({ to: { id: billingByCompany[cid] }, types: [{ associationCategory: cat, associationTypeId: cfg.assocTypeIds.invoiceToContact }] });
  }
  return { properties: { hs_currency: cfg.invoiceCurrency, hs_invoice_date: issueDate, hs_due_date: dueDate, type: cfg.invoiceType }, associations };
});
return [{ json: { ...ctx, issues, billingByCompany, invoiceInputs, invoiceDate: issueDate } }];

const ctx = $input.first().json;
const size = $('Workflow Config').first().json.batchSize;
const list = ctx.invoiceInputs;
const chunks = [];
for (let i = 0; i < list.length; i += size) chunks.push(list.slice(i, i + size));
// FAN-OUT: one item per batch of up to batchSize records. The HTTP node below runs once per batch.
return chunks.map(inputs => ({ json: { inputs } }));

const plan = $('Plan Invoice Creates').first().json;
const size = $('Workflow Config').first().json.batchSize;
const ids = [];
for (const item of $input.all()) {
  const r = item.json;
  if (r.numErrors > 0 || (r.errors && r.errors.length)) {
    throw new Error(`Invoice batch create failed: ${JSON.stringify(r.errors)}. Drafts created so far are archived by the next run.`);
  }
  for (const inv of r.results || []) ids.push(String(inv.id));
}
if (ids.length !== plan.invoiceInputs.length) {
  throw new Error(`Created ${ids.length} of ${plan.invoiceInputs.length} draft invoices. Not continuing; the drafts are archived by the next run.`);
}
const chunks = [];
for (let i = 0; i < ids.length; i += size) chunks.push(ids.slice(i, i + size));
// FAN-OUT: batches of created invoice ids. Which invoice belongs to which company is read back from HubSpot rather than assumed from response order.
return chunks.map(c => ({ json: { ids: c } }));

const ctx = $('Plan Invoice Creates').first().json;
const cfg = $('Workflow Config').first().json;
const invoiceByCompany = {};
for (const item of $input.all()) {
  const r = item.json;
  if (r.numErrors > 0 || (r.errors && r.errors.length)) {
    throw new Error(`Invoice to company read returned errors: ${JSON.stringify(r.errors)}`);
  }
  for (const row of r.results || []) {
    const cid = String(((row.to || [])[0] || {}).toObjectId);
    if (invoiceByCompany[cid]) throw new Error(`Company ${cid} ended up with two new invoices (${invoiceByCompany[cid]}, ${row.from.id}). Stopping before line items are created.`);
    invoiceByCompany[cid] = String(row.from.id);
  }
}
const lineItemInputs = [];
for (const cid of ctx.planIds) {
  if (!invoiceByCompany[cid]) throw new Error(`No newly created invoice found for company ${cid}. Stopping before line items are created; the drafts are archived by the next run.`);
  for (const properties of ctx.plans[cid]) {
    lineItemInputs.push({
      properties,
