const ctx = $('Collect Invoice Line Items Links').first().json;
const cfg = $('Workflow Config').first().json;
const lineItemById = {};
for (const item of $input.all()) {
  const r = item.json;
  if (!Array.isArray(r.results)) continue;             // the no-line-items path passes the context item straight through
  if (r.numErrors > 0 || (r.errors && r.errors.length)) {
    throw new Error(`Line item read returned errors: ${JSON.stringify(r.errors)}`);
  }
  for (const li of r.results) lineItemById[String(li.id)] = li;
}
const prepared = [];
const failures = [];
for (const inv of ctx.xeroInvoices) {
  const company = ctx.companies[inv.companyId] || {};
  const ownerId = inv.ownerId || company.ownerId || null;
  const base = { hubspotInvoiceId: String(inv.invoiceId), invoiceNumber: inv.number || null, ownerId, purchaseOrderNumber: inv.po || '' };
  const fail = (msg) => failures.push({ ...base, stage: 'Prepare Xero invoice', errorMessage: msg });
  if (!company.xeroContactId) { fail(`${company.name || 'Company'} has no xero_customer_id on its HubSpot company record, so the invoice cannot be created in Xero.`); continue; }
  if (ctx.pagedInvoiceIds.includes(inv.invoiceId)) { fail('Invoice has more line items than one HubSpot read returns.'); continue; }
  const ids = ctx.lineItemIdsByInvoice[inv.invoiceId] || [];
  if (!ids.length) { fail('HubSpot invoice has no line items.'); continue; }
  const region = String(company.state || '').trim().toUpperCase();
  const accountCode = cfg.stateAccounts[region] || cfg.defaultAccountId;
  try {
    const lineItems = ids.map(id => {
      const li = lineItemById[String(id)];
      if (!li) throw new Error(`Line item ${id} could not be read from HubSpot`);
      const p = li.properties || {};
      const amount = parseFloat(p.amount != null ? p.amount : parseFloat(p.price) * parseFloat(p.quantity == null ? 1 : p.quantity));
      if (!Number.isFinite(amount)) throw new Error(`Line item ${id} has a non-numeric amount`);
      const first = [p.asset_number, 'Weekly Invoice', p.name].filter(Boolean).join(' | ');
      const description = p.serial_number ? `${first}\nSerial Number ${p.serial_number}` : first;
      const line = { Description: description, Quantity: 1, UnitAmount: amount, AccountCode: accountCode, LineAmount: amount };
      if (p.asset_number) line.ItemCode = p.asset_number;
      return line;
    });
    const xeroInvoice = {
      Type: 'ACCREC', Contact: { ContactID: company.xeroContactId }, Date: inv.date, DueDate: inv.dueDate,
      InvoiceNumber: inv.number, Reference: inv.po, Status: cfg.invoiceStatus, CurrencyCode: cfg.currency,
      BrandingThemeID: cfg.brandingThemeId, LineItems: lineItems
    };
    prepared.push({ ...base, xeroInvoice });
  } catch (e) {
    fail(e.message);
  }
}
const { xeroInvoices, lineItemIdsByInvoice, lineItemIds, pagedInvoiceIds, ...rest } = ctx;
return [{ json: { ...rest, prepared, failures } }];

const size = $('Workflow Config').first().json.batchSize;
const failures = $input.first().json.failures;
const taskInputs = failures.map(p => {
  const properties = {
    hs_task_subject: `Xero sync error - Invoice ${p.purchaseOrderNumber || p.invoiceNumber || p.hubspotInvoiceId}`,
    hs_task_body: `An error occurred while preparing this invoice for Xero.\n\nFailed step: ${p.stage}\nHubSpot invoice ID: ${p.hubspotInvoiceId}\nInvoice number: ${p.invoiceNumber ?? ''}\nPO Number: ${p.purchaseOrderNumber ?? ''}\nError: ${String(p.errorMessage).slice(0, 2000)}\n\nThe HubSpot invoice is open but not in Xero. Fix the cause; a re-run the same day retries it automatically.`,
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: 'HIGH',
    hs_task_type: 'TODO',
    hs_timestamp: new Date().toISOString()
  };
  if (p.ownerId) properties.hubspot_owner_id = p.ownerId;
  return { properties };
});
const chunks = [];
for (let i = 0; i < taskInputs.length; i += size) chunks.push(taskInputs.slice(i, i + size));
// FAN-OUT: one item per batch of tasks. Emits nothing when there are no failures, which simply ends this side branch.
return chunks.map(inputs => ({ json: { inputs } }));

// Turns this batch of prepared invoices into ONE Xero request body.
const MAX_BATCH = 100;           // HubSpot batch update / task-create endpoints accept at most 100 records
const MAX_BYTES = 3000000;       // Xero rejects a POST over 3.5 MB; stay clear of it

const items = $input.all();
if (!items.length) throw new Error('Build Xero Batch Payload received no invoices');
if (items.length > MAX_BATCH) {
  throw new Error(`Batch of ${items.length} exceeds ${MAX_BATCH}. Lower xeroBatchSize in Workflow Config.`);
}

// Drop null / empty values - a blank field can make Xero reject an otherwise valid invoice.
const clean = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== null && v !== undefined && v !== ''));

const payload = { Invoices: items.map((i) => clean(i.json.xeroInvoice)) };

const bytes = JSON.stringify(payload).length;
if (bytes > MAX_BYTES) {
  throw new Error(`Batch payload is ${bytes} bytes (limit ~3.5 MB). Lower xeroBatchSize in Workflow Config.`);
}

// What we sent, in the same order - used to match Xero's response back to HubSpot records.
const submitted = items.map((i) => ({
  hubspotInvoiceId: String(i.json.hubspotInvoiceId),
  invoiceNumber: i.json.invoiceNumber ?? null,
  ownerId: i.json.ownerId ?? null,
  purchaseOrderNumber: i.json.purchaseOrderNumber ?? '',
}));

const batchNumber = $runIndex + 1;
console.log(`Batch ${batchNumber}: ${items.length} invoice(s), ${bytes} bytes`);

return [{ json: { batchNumber, count: items.length, payloadBytes: bytes, payload, submitted } }];

// Xero returns HTTP 200 for a batch even when individual invoices were rejected, so every invoice
// is checked on its own. Results are matched to HubSpot records by position AND invoice number.
const ZERO_GUID = '00000000-0000-0000-0000-000000000000';
const build = $('Build Xero Batch Payload').first().json;
const submitted = build.submitted;
const resp = $input.first().json;

const failAll = (stage, errorMessage) => [{
  json: {
    batchNumber: build.batchNumber,
    okInvoices: [],
    failures: submitted.map((s) => ({ ...s, stage, errorMessage })),
  },
}];

// 1. The whole request failed (network, auth, 4xx/5xx, timeout)
if (resp.error || !Array.isArray(resp.Invoices)) {
  const e = resp.error;
  const detail = typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(' - ') || 'no Invoices array in the response';
  return failAll('Xero create (whole batch)', `Xero batch request failed: ${detail}. No invoices from this batch were written to HubSpot.`);
}

// 2. Positional mapping is only safe if the counts and invoice numbers line up
const returned = resp.Invoices;
const numberMismatch = returned.some((inv, i) => submitted[i] && submitted[i].invoiceNumber && inv.InvoiceNumber && inv.InvoiceNumber !== submitted[i].invoiceNumber);
if (returned.length !== submitted.length || numberMismatch) {
  return failAll('Xero create (response mismatch)',
    `Xero returned ${returned.length} invoice(s) for ${submitted.length} submitted (or invoice numbers did not line up), so results cannot be matched safely. Some invoices may exist in Xero - check Xero for this batch before re-running. Nothing was written to HubSpot.`);
}

// 3. Per-invoice outcome
const okInvoices = [];
const failures = [];
returned.forEach((inv, i) => {
  const s = submitted[i];
  const errs = (inv.ValidationErrors || []).map((e) => e.Message).filter(Boolean);
  const created = inv.InvoiceID && inv.InvoiceID !== ZERO_GUID && inv.StatusAttributeString !== 'ERROR' && !inv.HasErrors;
  if (created) {
    okInvoices.push({ ...s, xeroInvoiceId: inv.InvoiceID });
  } else {
    failures.push({ ...s, stage: 'Xero create', errorMessage: errs.length ? errs.join(' | ') : `Xero rejected the invoice (status ${inv.StatusAttributeString ?? 'unknown'})` });
  }
});

console.log(`Batch ${build.batchNumber}: ${okInvoices.length} created, ${failures.length} rejected`);
return [{ json: { batchNumber: build.batchNumber, okInvoices, failures } }];

// Gathers every failure from this batch into HubSpot task inputs (one per invoice, assigned to the invoice owner).
// Input is EITHER the write-back response (when invoices were created) OR the parsed result itself (when none were).
const parsed = $('Parse Xero Batch Results').first().json;
const incoming = $input.first().json;
const ranWriteBack = !Array.isArray(incoming.okInvoices);

const problems = parsed.failures.map((f) => ({ ...f }));

if (ranWriteBack && parsed.okInvoices.length) {
  let missed = [];
  let reason = '';
  if (incoming.error) {
    const e = incoming.error;
    reason = typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(' - ') || 'unknown error';
    missed = parsed.okInvoices;
  } else {
    const done = new Set((incoming.results || []).map((r) => String(r.id)));
    missed = parsed.okInvoices.filter((o) => !done.has(String(o.hubspotInvoiceId)));
    reason = incoming.errors?.[0]?.message ?? 'HubSpot did not confirm the update';
  }
  for (const o of missed) {
    problems.push({
      ...o,
      stage: 'HubSpot write-back',
      errorMessage: `The Xero invoice WAS created (Xero InvoiceID ${o.xeroInvoiceId}) but xero_invoice_id could not be saved on the HubSpot invoice: ${reason}. Set it manually before the next run or the invoice may be created twice.`,
    });
  }
}

const taskInputs = problems.map((p) => {
  const properties = {
    hs_task_subject: `Xero sync error - Invoice ${p.purchaseOrderNumber || p.invoiceNumber || p.hubspotInvoiceId}`,
    hs_task_body: `An error occurred while syncing this invoice to Xero.\n\nFailed step: ${p.stage}\nHubSpot invoice ID: ${p.hubspotInvoiceId}\nInvoice number: ${p.invoiceNumber ?? ''}\nPO Number: ${p.purchaseOrderNumber ?? ''}\nBatch: ${parsed.batchNumber}\nError: ${String(p.errorMessage).slice(0, 2000)}`,
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: 'HIGH',
    hs_task_type: 'TODO',
    hs_timestamp: new Date().toISOString(),
  };
  if (p.ownerId) properties.hubspot_owner_id = p.ownerId;
  return { properties };
});

return [{ json: {
  batchNumber: parsed.batchNumber,
  created: parsed.okInvoices.length - problems.filter((p) => p.stage === 'HubSpot write-back').length,
  failed: problems.length,
  taskInputs,
} }];

const ctx = $('Gather Xero Invoices').first().json;
const counts = {};
for (const o of Object.values(ctx.outcomes)) counts[o.status] = (counts[o.status] || 0) + 1;
console.log(`HubSpot: ${JSON.stringify(counts)}. Invoices considered for Xero: ${ctx.xeroCandidates.length}.`);
if (ctx.issues.length) {
  const list = ctx.issues.slice(0, 20).map(i => `- ${i}`).join('\n');
  throw new Error(`Weekly invoicing finished with ${ctx.issues.length} issue(s) that need a person (everything else completed). HubSpot: ${JSON.stringify(counts)}\n${list}`);
}
return [{ json: { counts, invoicesConsideredForXero: ctx.xeroCandidates.length } }];
